mapper.update:
update trade_order
set order_status   = #{status},
    transaction_id = #{transactionId}
where out_trade_no = #{outTradeNo}
  and order_status in (1, 2)

mapper.select:
select o.order_id as id, o.out_trade_no as outTradeNo, o.goods_id as goodsId, o.snapshot_id as snapshotId, o.goods_title as goodsTitle, o.goods_price as goodsPrice, o.quantity as quantity, o.total_amount as totalAmount, o.goods_image as goodsImage, o.goods_description as goodsDescription, o.order_status as orderStatus, if(o.order_status = 1 and timestampdiff(MINUTE, o.create_time, now()) > 20, true, false) as disabled, date_format(o.create_date, '%Y-%m-%d') as createDate, date_format(o.create_time, '%Y-%m-%d %H:%i:%s') as createTime, count(a.order_id) as appointCount from trade_order o left join med_exam_appointment a on o.order_id = a.order_id where o.customer_id = #{customerId}
and o.order_status = #{orderStatus}
and ( o.out_trade_no like concat('%', #{keyword} ,'%') OR o.goods_title like concat('%', #{keyword} ,'%'))
group by o.order_id order by o.order_id desc limit #{startIndex}, #{pageSize}

select count(*)
from trade_order o
where o.customer_id = #{customerId}

    and o.order_status = #{orderStatus}


    and ( o.out_trade_no like concat('%', #{keyword} ,'%') OR o.goods_title like concat('%', #{keyword} ,'%'))

select transaction_id as transactionId, total_amount as totalAmount
from trade_order
where order_id = #{orderId}
  and customer_id = #{customerId}
  and order_status = 3 limit 1

select o.goods_title as goodsTitle, o.goods_price as goodsPrice, o.quantity, o.total_amount as totalAmount, o.order_status as orderStatus, date_format(o.create_time, '%Y-%m-%d %H:%i') as createTime, o.create_date as createDate, date_format(o.refund_time, '%Y-%m-%d %H:%i') as refundTime, o.refund_date as refundDate, o.order_id as orderId, c.photo_url as photoUrl, c.customer_name as customerName, c.gender, c.phone, date_format(c.register_time, '%Y-%m-%d') as registerTime, o.out_trade_no as outTradeNo, o.transaction_id as transactionId, o.out_refund_no as outRefundNo, o.snapshot_id as snapshotId, count(a.order_id) as num from med_exam_package p join trade_order o on p.id = o.goods_id join crm_customer c on c.id = o.customer_id left join med_exam_appointment a on a.order_id = o.order_id
p.package_code like concat('%',#{packageCode},'%')
and o.goods_title like concat('%',#{keyword},'%')
and c.phone = #{phone}
and o.order_status = #{orderStatus}
and o.create_date between #{startDate} and #{endDate}
and o.customer_id = #{customerId}
group by o.order_id order by o.order_id desc limit #{startIndex}, #{pageSize}

select count(*) from med_exam_package p join trade_order o on p.id = o.goods_id join crm_customer c on c.id = o.customer_id
p.package_code like concat('%',#{packageCode},'%')
and o.goods_title like concat('%',#{keyword},'%')
and c.phone = #{phone}
and o.order_status = #{orderStatus}
and o.create_date between #{startDate} and #{endDate}
and o.customer_id = #{customerId}

